<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue"; import { api, errorText } from "../api"; import { usePlatformStore } from "../stores/platform"; import { formatBeijing } from "../utils";
const store=usePlatformStore(); const page=ref(1); const filters=reactive({keyword:"",ecosystem:"all",severity:"all",risk:"all",dependency:"all"});
const toolHealth=ref<any>(null),policies=ref<any>(null),exceptions=ref<any[]>([]),vex=ref<any[]>([]),intelligence=ref<any>(null),scaEvidence=ref<any>(null),policyAudit=ref<any[]>([]),message=ref("");
const exceptionDraft=reactive({component_id:"",reason:"",requester:"",requester_role:"developer",expires_at:""}); const vexDraft=reactive({component_id:"",vulnerability_id:"",status:"not_affected",justification:"",actor:""}); const importDraft=reactive({kind:"intelligence",source:"manual-import",entries:""});
const policyDraft=reactive({scope:"project",kind:"vulnerability",id:"",config:""});
const risky=computed(()=>store.components.filter(i=>i.risk_status&&!["clean","not_affected","fixed"].includes(i.risk_status))); const high=computed(()=>risky.value.filter(i=>["critical","high"].includes(i.severity)));
const unique=(key:string)=>[...new Set(store.components.map(i=>i[key]??"none"))];
const filtered=computed(()=>store.components.filter(i=>{const q=filters.keyword.trim().toLowerCase();return(!q||`${i.name} ${i.version??""} ${(i.vulnerability_ids??[]).join(" ")}`.toLowerCase().includes(q))&&(filters.ecosystem==="all"||i.ecosystem===filters.ecosystem)&&(filters.severity==="all"||(i.severity??"none")===filters.severity)&&(filters.risk==="all"||(i.risk_status??"not_checked")===filters.risk)&&(filters.dependency==="all"||i.dependency_type===filters.dependency)})); const pageCount=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10))); const items=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10));
const severity=(v:any)=>({critical:"严重",high:"高危",medium:"中危",low:"低危",info:"提示",none:"未评级"}[v as string]??v??"未评级"); const risk=(v:any)=>({vulnerable:"存在漏洞",license_risk:"许可证风险",version_unknown:"版本未知",accepted_risk:"已接受风险",clean:"未发现风险",not_checked:"未检查"}[v as string]??v??"未检查"); const dep=(v:any)=>({direct:"直接依赖",transitive:"传递依赖",unknown:"未知"}[v as string]??v??"未知");
async function loadAdvanced(){if(!store.project)return;const id=store.project.id;const suffix=store.scaScanId?`?scan_task_id=${store.scaScanId}`:"";[toolHealth.value,policies.value,exceptions.value,vex.value,intelligence.value,scaEvidence.value,policyAudit.value]=await Promise.all([api<any>("/sca/tool-health").catch(()=>null),api<any>(`/sca/policies?project_id=${id}`).catch(()=>null),api<any[]>(`/sca/projects/${id}/exceptions`).catch(()=>[]),api<any[]>(`/sca/projects/${id}/vex`).catch(()=>[]),api<any>("/sca/intelligence/status").catch(()=>null),api<any>(`/sca/projects/${id}/evidence${suffix}`).catch(()=>null),api<any[]>(`/sca/projects/${id}/policy-audit`).catch(()=>[])])}
async function addException(){if(!store.project)return;const c=store.components.find(i=>i.id===exceptionDraft.component_id);if(!c||!exceptionDraft.reason)return;try{await api(`/sca/projects/${store.project.id}/exceptions`,{method:"POST",body:JSON.stringify({ecosystem:c.ecosystem,package_name:c.name,package_version:c.version,exception_type:"risk_acceptance",reason:exceptionDraft.reason,requester:exceptionDraft.requester||null,requester_role:exceptionDraft.requester_role,expires_at:exceptionDraft.expires_at||null})});await loadAdvanced()}catch(e){message.value=errorText(e)}}
async function decide(id:string,status:string){await api(`/sca/exceptions/${id}`,{method:"PATCH",body:JSON.stringify({status,approver:"platform-admin",approver_role:"security"})});await loadAdvanced()}
async function addVex(){if(!store.project)return;const c=store.components.find(i=>i.id===vexDraft.component_id);if(!c||!vexDraft.vulnerability_id)return;try{await api(`/sca/projects/${store.project.id}/vex`,{method:"POST",body:JSON.stringify({ecosystem:c.ecosystem,package_name:c.name,package_version:c.version,vulnerability_id:vexDraft.vulnerability_id,status:vexDraft.status,justification:vexDraft.justification||null,actor:vexDraft.actor||null})});await loadAdvanced()}catch(e){message.value=errorText(e)}}
async function importEntries(){try{const entries=JSON.parse(importDraft.entries);if(!Array.isArray(entries))throw new Error("请输入 JSON 数组");await api(importDraft.kind==="osv"?"/sca/osv-mirror/import":"/sca/intelligence/import",{method:"POST",body:JSON.stringify({entries,source:importDraft.source})});importDraft.entries="";await loadAdvanced()}catch(e){message.value=errorText(e)}}
async function togglePolicy(kind:string,id:string,enabled:boolean){if(!store.project)return;try{await api("/sca/policies/overrides",{method:"POST",body:JSON.stringify({project_id:store.project.id,policy_kind:kind,policy_id:id,enabled,actor:"platform-admin",change_note:`通过治理页${enabled?'启用':'停用'}策略`})});await loadAdvanced()}catch(e){message.value=errorText(e)}}
async function savePolicy(){if(!policyDraft.id||!policyDraft.config)return;try{const config=JSON.parse(policyDraft.config);await api("/sca/policies/overrides",{method:"POST",body:JSON.stringify({project_id:policyDraft.scope==='project'?store.project?.id:null,policy_kind:policyDraft.kind,policy_id:policyDraft.id,enabled:true,config,actor:"platform-admin",change_note:"通过治理页新增或覆盖策略"})});policyDraft.id="";policyDraft.config="";await loadAdvanced()}catch(e){message.value=errorText(e)}}
onMounted(loadAdvanced);
</script>
<template><div class="module-governance-view">
  <section class="module-governance-hero panel"><div><span class="section-kicker">SCA 供应链风险</span><h2>检查第三方组件、已知漏洞和许可证风险</h2></div><div class="module-run-actions"><span>{{ store.moduleStatus.sca }}</span><button class="primary-action" :disabled="store.moduleLoading.sca" @click="store.scan('sca')">{{ store.moduleLoading.sca?"执行中":"重新扫描并复测" }}</button></div></section>
  <section class="governance-metrics"><div class="metric-card"><span>当前组件数</span><strong>{{ store.components.length }}</strong></div><div class="metric-card"><span>风险组件数</span><strong>{{ risky.length }}</strong></div><div class="metric-card"><span>严重 / 高危组件</span><strong>{{ high.length }}</strong></div><div class="metric-card"><span>建议升级组件</span><strong>{{ risky.filter(i=>i.remediation).length }}</strong></div></section>
  <section class="panel"><div class="panel-header"><h2>主要结果</h2><span>完整结果 · 每页 10 条</span></div><div class="module-filter-bar"><input v-model="filters.keyword" placeholder="搜索组件、版本或漏洞标识"/><select v-model="filters.ecosystem"><option value="all">全部生态</option><option v-for="v in unique('ecosystem')" :key="v">{{ v }}</option></select><select v-model="filters.severity"><option value="all">全部等级</option><option v-for="v in unique('severity')" :key="v" :value="v">{{ severity(v) }}</option></select><select v-model="filters.risk"><option value="all">全部风险状态</option><option v-for="v in unique('risk_status')" :key="v" :value="v">{{ risk(v) }}</option></select><select v-model="filters.dependency"><option value="all">全部依赖类型</option><option v-for="v in unique('dependency_type')" :key="v" :value="v">{{ dep(v) }}</option></select></div>
    <table class="concise-table"><thead><tr><th>组件</th><th>风险状态</th><th>漏洞标识</th><th>建议动作</th></tr></thead><tbody><tr v-if="!items.length"><td colspan="4" class="empty-cell">没有符合筛选条件的组件。</td></tr><tr v-for="item in items" :key="item.id"><td><strong>{{ item.name }}</strong><span class="cell-subtext">{{ item.version??'版本未知' }} · {{ item.ecosystem }} · {{ dep(item.dependency_type) }}</span></td><td>{{ risk(item.risk_status) }}<span class="cell-subtext">{{ severity(item.severity) }}</span></td><td>{{ item.vulnerability_ids?.join(', ')||'无已知漏洞标识' }}</td><td>{{ item.remediation??(risky.includes(item)?'确认可用安全版本后升级':'暂不需要处理') }}</td></tr></tbody></table><div class="result-pagination"><span>共 {{ filtered.length }} 条，每页 10 条</span><div><button :disabled="page<=1" @click="page--">上一页</button><strong>第 {{ page }} / {{ pageCount }} 页</strong><button :disabled="page>=pageCount" @click="page++">下一页</button></div></div>
    <section class="advanced-inline-action"><div><strong>扫描报告</strong><span>扫描完成后可导出当前项目的 SCA 风险、组件和修复建议，无需配置 Docker 或离线情报。</span></div><div class="advanced-actions"><button class="secondary-action" :disabled="!store.components.length" @click="store.exportScaReport">导出 SCA 报告</button></div></section>
    <section class="retest-panel"><div class="panel-header"><h3>最近一次风险记录复测</h3><span>{{ store.retests.sca?.previous_scan_at?formatBeijing(store.retests.sca.previous_scan_at):'等待第二次扫描' }} → {{ store.retests.sca?.current_scan_at?formatBeijing(store.retests.sca.current_scan_at):'-' }}</span></div><div class="retest-summary"><div class="metric-card"><span>仍然存在的风险记录</span><strong>{{ store.retests.sca?.still_present_count??0 }}</strong></div><div class="metric-card"><span>已消失的风险记录</span><strong>{{ store.retests.sca?.resolved_count??0 }}</strong></div><div class="metric-card"><span>新增风险记录</span><strong>{{ store.retests.sca?.new_count??0 }}</strong></div><div class="metric-card"><span>内容发生变化</span><strong>{{ store.retests.sca?.changed_count??0 }}</strong></div></div><p class="retest-note">这里统计的是风险记录，不是组件数量。SCA 中一个组件可能同时对应多个漏洞、许可证或版本风险，因此风险记录数可能大于组件数。</p></section>
  </section>
  <section class="next-action-panel"><strong>建议动作</strong><span>{{ risky.length?'优先升级高危组件，并确认升级是否影响直接和传递依赖。':'当前未发现高风险组件，建议定期重新扫描依赖。' }}</span></section>
  <details class="advanced-details"><summary>高级设置（可选）：离线扫描、依赖分析与 CI 发布检查</summary><div class="advanced-details-body">
    <details class="advanced-details"><summary>Docker 增强扫描与 SBOM 导出（可选）</summary><div class="advanced-details-body"><section class="advanced-inline-action"><div><strong>外部扫描工具</strong><span>仅在需要更完整的软件物料清单（SBOM）或已准备 Docker 时启用；未启用不影响基础 SCA 扫描。</span></div><div class="advanced-actions"><label class="inline-check"><input v-model="store.scaEnhanced" type="checkbox"/>使用 Docker 增强扫描</label><button class="secondary-action" @click="store.exportSbom('cyclonedx')">导出 CycloneDX</button><button class="secondary-action" @click="store.exportSbom('spdx')">导出 SPDX</button></div></section><section class="panel"><div class="panel-header"><h3>Docker 增强扫描准备情况</h3><span>{{ toolHealth?.status??toolHealth?.overall_status??'未检查' }}</span></div><label>本模块源码路径<input v-model="store.scaPath" /></label><pre class="json-preview">{{ JSON.stringify(toolHealth??{},null,2) }}</pre></section></div></details>
    <details class="advanced-details"><summary>离线漏洞数据与扫描依据（可选）</summary><div class="advanced-details-body"><section class="panel"><div class="panel-header"><h3>补充风险数据</h3><span>{{ intelligence?.status??'未配置' }}</span></div><div class="filter-grid"><select v-model="importDraft.kind"><option value="intelligence">CVSS / EPSS / KEV</option><option value="osv">OSV 镜像</option></select><input v-model="importDraft.source"/><textarea v-model="importDraft.entries" placeholder="JSON 数组"/><button class="secondary-action" @click="importEntries">导入数据</button></div></section><section class="panel full"><div class="panel-header"><h3>扫描依据与发布检查</h3><span>当前 SCA 批次证据</span></div><div class="metric-grid"><div class="metric-card"><span>CI 门禁</span><strong>{{ scaEvidence?.gate?.decision??'未生成' }}</strong></div><div class="metric-card"><span>阻断组件</span><strong>{{ scaEvidence?.gate?.blocked_component_count??0 }}</strong></div><div class="metric-card"><span>哈希算法</span><strong>{{ scaEvidence?.artifact_hashes?.algorithm??'-' }}</strong></div><div class="metric-card"><span>策略快照</span><strong>{{ scaEvidence?.policy_snapshot?.enabled_vulnerability_rule_count??0 }}</strong></div></div><details><summary>查看完整扫描证据</summary><pre class="json-preview">{{ JSON.stringify(scaEvidence??{},null,2) }}</pre></details></section></div></details>
    <details class="advanced-details"><summary>风险例外、适用性与扫描规则（可选）</summary><div class="advanced-details-body"><section class="panel full"><div class="panel-header"><h3>风险例外审批</h3><span>{{ exceptions.length }} 条</span></div><div class="filter-grid"><select v-model="exceptionDraft.component_id"><option value="">选择当前风险组件</option><option v-for="i in risky" :key="i.id" :value="i.id">{{ i.name }} {{ i.version }}</option></select><input v-model="exceptionDraft.reason" placeholder="接受风险的业务原因"/><input v-model="exceptionDraft.requester" placeholder="申请人"/><input v-model="exceptionDraft.expires_at" type="date"/><button class="secondary-action" @click="addException">提交例外申请</button></div><table class="compact-table"><tbody><tr v-for="i in exceptions" :key="i.id"><td>{{ i.package_name }}</td><td>{{ i.reason }}</td><td>{{ i.status }}</td><td><button v-if="i.status==='pending'" @click="decide(i.id,'approved')">批准</button><button v-if="i.status==='approved'" @click="decide(i.id,'revoked')">撤销</button></td></tr></tbody></table></section><section class="panel full"><div class="panel-header"><h3>VEX 适用性结论</h3><span>{{ vex.length }} 条</span></div><div class="filter-grid"><select v-model="vexDraft.component_id" @change="vexDraft.vulnerability_id=store.components.find(i=>i.id===vexDraft.component_id)?.vulnerability_ids?.[0]??''"><option value="">选择组件</option><option v-for="i in store.components.filter(i=>i.vulnerability_ids?.length)" :key="i.id" :value="i.id">{{ i.name }}</option></select><input v-model="vexDraft.vulnerability_id" placeholder="漏洞 ID"/><select v-model="vexDraft.status"><option value="not_affected">未受影响</option><option value="fixed">已修复</option><option value="affected">受影响</option><option value="under_investigation">调查中</option></select><textarea v-model="vexDraft.justification"/><button class="secondary-action" @click="addVex">保存 VEX 结论</button></div></section><section class="panel full"><div class="panel-header"><h3>本地 SCA 策略与项目覆盖</h3><span>当前扫描使用的规则、启停和审计</span></div><table class="compact-table"><thead><tr><th>策略</th><th>范围</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="i in policies?.vulnerability_rules??[]" :key="`v-${i.id}`"><td>{{ i.id }}<span class="cell-subtext">{{ i.ecosystem }} · {{ i.package }}</span></td><td>漏洞</td><td>{{ i.enabled?'已启用':'已停用' }}</td><td><button class="secondary-action" @click="togglePolicy('vulnerability',i.id,!i.enabled)">{{ i.enabled?'停用':'启用' }}</button></td></tr><tr v-for="i in policies?.license_policies??[]" :key="`l-${i.id}`"><td>{{ i.id }}<span class="cell-subtext">{{ i.policy }}</span></td><td>许可证</td><td>{{ i.enabled!==false?'已启用':'已停用' }}</td><td><button class="secondary-action" @click="togglePolicy('license',i.id,i.enabled===false)">{{ i.enabled!==false?'停用':'启用' }}</button></td></tr></tbody></table><details><summary>新增或覆盖策略</summary><div class="filter-grid"><select v-model="policyDraft.scope"><option value="project">当前项目</option><option value="platform">平台级</option></select><select v-model="policyDraft.kind"><option value="vulnerability">漏洞规则</option><option value="license">许可证策略</option><option value="gate">CI 门禁策略</option></select><input v-model="policyDraft.id" placeholder="策略 ID"/><textarea v-model="policyDraft.config" placeholder="策略 JSON 对象"/><button class="secondary-action" @click="savePolicy">保存策略</button></div></details><details><summary>策略审计记录（{{ policyAudit.length }} 条）</summary><pre class="json-preview">{{ JSON.stringify(policyAudit,null,2) }}</pre></details></section></div></details>
    <details class="advanced-details"><summary>扫描历史与依赖关系分析（可选）</summary><div class="advanced-details-body"><section class="panel"><div class="panel-header"><h3>扫描历史</h3><span>{{ store.scaHistory.length }} 个批次</span></div><table class="compact-table"><tbody><tr v-for="i in store.scaHistory" :key="i.scan_task_id"><td>{{ i.scan_task_id.slice(0,8) }}</td><td>{{ formatBeijing(i.created_at) }}</td><td><button class="secondary-action" @click="store.selectScaSnapshot(i.scan_task_id)">{{ i.scan_task_id===store.scaScanId?'当前批次':'查看快照' }}</button></td></tr></tbody></table></section><section class="panel"><div class="panel-header"><h3>依赖关系与升级建议</h3><span>{{ store.dependencyGraph?.summary?.node_count??0 }} 个节点</span></div><pre class="json-preview">{{ JSON.stringify(store.dependencyGraph??{},null,2) }}</pre></section></div></details>
  </div></details><p>{{ message }}</p>
</div></template>
